function memberSearchFilter(row: {
    original: MemberDepartmentMember;
}, _columnId: string, filterValue: unknown) {
    const query = String(filterValue ?? "").trim().toLocaleLowerCase();
    if (!query)
        return true;
    return [
        row.original.name,
        row.original.email,
        row.original.phone,
        row.original.functionGroup,
        row.original.departmentPath.join(" "),
    ]
        .filter(Boolean)
        .join(" ")
        .toLocaleLowerCase()
        .includes(query);
}
