export function MemberDepartment({ "aria-label": ariaLabel, className, defaultView = "members", departmentDirectory = defaultMemberDepartmentDirectory, departments = defaultMemberDepartmentTree, isLoading = false, labels: providedLabels, members = defaultMemberDepartmentMembers, onCreateDepartment, onCreateMember, onDepartmentSelect, onDepartmentExpand, onDepartmentOpen, onMemberOpen, onViewChange, view: controlledView, ...props }: MemberDepartmentProps) {
