                  </div>
                </DataTable>
              </div>
            </div>
          </PageBody>
        </PageContent>
      </PageLayout>
      <MobileDrawer ariaLabel={labels.departmentTree} onClose={() => setIsDepartmentDrawerOpen(false)} open={isDepartmentDrawerOpen}>
        {tree}
      </MobileDrawer>
    </section>);
}

